:var(--muted);background:#21334b}.tool{padding:13px;margin:9px 0;border:1px solid var(--line);border-radius:13px;background:#132238aa}.tool:hover{border-color:#5e86aa;background:#182a43}.tool-title{display:flex;align-items:center;justify-content:space-between;gap:8px}.tool-name{font-weight:800;color:#f2f7ff}.tool-desc{color:var(--muted);font-size:12px;margin:5px 0 10px}.cap{color:#7fcae5;font-size:10px;margin-right:4px}.form{border-top:1px solid var(--line);padding-top:9px}.field{display:block;margin:8px 0;color:#b6c8df;font-size:12px}.field input,.field textarea,.field select{width:100%;margin-top:5px;background:#091423;border:1px solid var(--line);border-radius:8px;padding:8px}.field textarea{min-height:64px;resize:vertical}.workspace{min-width:0;display:grid;grid-template-columns:minmax(210px,.36fr) minmax(0,1fr);gap:14px}.history,.result{min-width:0;padding:16px}.history{max-height:calc(100vh - 42px);overflow:auto}.history-item{padding:11px;border:1px solid transparent;border-radius:11px;margin:7px 0;cursor:pointer;background:#101e31}.history-item:hover,.history-item.active{border-color:#557ca1;background:#172b45}.history-name{font-weight:750;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.history-meta{display:flex;justify-content:space-between;gap:8px;color:var(--muted);font-size:11px;margin-top:4px}.status{font-weight:800}.status.ok{color:var(--good)}.status.bad{color:var(--bad)}.result{min-height:560px}.empty{display:grid;place-items:center;min-height:500px;color:var(--muted);text-align:center}.empty-icon{font-size:40px;color:#557ca1;margin-bottom:10px}.result-head{display:flex;justify-content:space-between;gap:12px;align-items:start;border-bottom:1px solid var(--line);padding-bottom:14px}.result-head h2{font-size:18px;margin:0}.badges{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}.badge{border-radius:8px;padding:4px 8px;background:#1d3048;color:#abc3df;font-size:11px}.badge.ok{color:var(--good);background:#153a35}.badge.bad{color:va