6px;flex-wrap:wrap;margin-top:10px}.inspector-actions .btn{padding:6px 9px;font-size:12px}@media(max-width:900px){.inspector-grid{grid-template-columns:1fr}.topbar{align-items:stretch;flex-direction:column}.token{width:100%}}</style></head>
