<header class="topbar"><div class="brand"><div class="mark"><svg viewBox="0 0 1024 1024" aria-label="Node Bridge" role="img"><rect width="1024" height="1024" rx="250" fill="#122A42"/><path d="M254 336 512 512 770 336M254 688 512 512l258 176M254 336v352M770 336v352" fill="none" stroke="url(#brandLine)" stroke-width="28" stroke-linecap="round" stroke-linejoin="round"/><defs><linearGradient id="brandLine" x1="170" y1="240" x2="850" y2="780" gradientUnits="userSpaceOnUse"><stop stop-color="#63E6D5"/><stop offset="1" stop-color="#8092FF"/></linearGradient></defs><circle cx="254" cy="336" r="79" fill="#0B1829" stroke="#63E6D5" stroke-width="22"/><circle cx="770" cy="336" r="79" fill="#0B1829" stroke="#8092FF" stroke-width="22"/><circle cx="254" cy="688" r="79" fill="#0B1829" stroke="#8092FF" stroke-width="22"/><circle cx="770" cy="688" r="79" fill="#0B1829" stroke="#63E6D5" stroke-width="22"/><circle cx="512" cy="512" r="102" fill="#0B1829" stroke="#F2F7FF" stroke-width="20"/><path d="M472 512h80M512 472v80" stroke="#F2F7FF" stroke-width="20" stroke-linecap="round"/></svg></div><div><div class="eyebrow">MCP SERVER</div><h1>$title</h1><div class="sub">Authenticated endpoint · <code>/mcp</code></div></div></div><div class="top-actions"><input class="input token" id="token" type="password" autocomplete="off" placeholder="${if (chinese) "请输入 Bearer Token" else "Bearer token"}"><button class="btn primary" id="refresh">${if (chinese) "加载工具" else "Load tools"}</button><select class="select" id="language">$languageOptions</select></div></header>
<section class="layout"><aside class="panel rail"><div class="panel-head"><h2>${if (chinese) "工具" else "Tools"}</h2><span class="count" id="toolCount">0</span></div><div class="hint">${if (chinese) "输入 Token 后加载工具，结果仅显示在当前页面。" else "Enter a token to load tools. Results stay on this page."}</div><div id="tools"><div class="empty-tools" id="toolEmpty">${if (chinese) "输入 Token 后加载工具" else "Enter a token, then load tools"}</div></div></aside>
<div class="workspace"><aside class="panel history"><div class="panel-head"><h2>${if (chinese) "调用记录" else "Call history"}</h2><button class="btn ghost" id="clear">${if (chinese) "清空" else "Clear"}</button></div><div class="hint" id="historyHint">${if (chinese) "状态、耗时和请求分开记录。" else "Status, duration, and requests are kept separate."}</div><div id="history"></div></aside>
 <section class="panel result" id="result"><div class="empty"><div><div class="empty-icon">◈</div><div>${if (chinese) "选择左侧工具开始调用" else "Choose a tool to start a call"}</div><div class="hint">${if (chinese) "截图结果会以图片预览显示" else "Screenshot content is rendered as an image preview"}</div></div></div></section></div></section></main>
<script>
$copy
let requestId=0, calls=[], selected=null; const toolsEl=document.querySelector('#tools'), historyEl=document.querySelector('#history'), resultEl=document.querySelector('#result'), tokenEl=document.querySelector('#token'); document.querySelector('#language').value='$languageCode';
document.querySelector('#language').onchange=async(e)=>{await fetch('/debug/locale',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({languageCode:e.target.value})});location.reload()};
document.querySelector('#clear').onclick=()=>{calls=[];selected=null;renderHistory();renderResult(null)};
function token(){return tokenEl.value.trim()}
function pretty(value){if(typeof value==='string'){try{return JSON.stringify(JSON.parse(value),null,2)}catch(_){return value}}return JSON.stringify(value,null,2)}
function field(name,schema){const label=document.createElement('label');label.className='field';label.textContent=name;let input;if(schema.enum){input=document.createElement('select');schema.enum.forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;input.appendChild(o)})}else if(name==='command'||(schema.type==='string'&&schema.maxLength>100)){input=document.createElement('textarea')}else{input=document.createElement('input');input.type=schema.type==='integer'?'number':schema.type==='boolean'?'checkbox':'text'}if(input.type!=='checkbox'){if(schema.minimum!==undefined)input.min=schema.minimum;if(schema.maximum!==undefined)input.max=schema.maximum;if(schema.maxLength!==undefined)input.maxLength=schema.maxLength}input.dataset.name=name;label.appendChild(input);return label}
function render(definitions){toolsEl.replaceChildren();document.querySelector('#toolCount').textContent=definitions.length;if(!definitions.length){const e=document.createElement('div');e.className='empty-tools';e.textContent=text.none;toolsEl.appendChild(e);return}definitions.forEach(def=>{const card=document.createElement('article');card.className='tool';const head=document.createElement('div');head.className='tool-title';const name=document.createElement('div');name.className='tool-name';name.textContent=def.name;const badge=document.createElement('span');badge.className='pill';badge.textContent=(def.requiredCapabilities||[]).length+' cap';head.append(name,badge);card.appendChild(head);const desc=document.createElement('div');desc.className='tool-desc';desc.textContent=def.description||'';card.appendChild(desc);(def.requiredCapabilities||[]).forEach(cap=>{const c=document.createElement('span');c.className='cap';c.textContent='◆ '+cap;card.appendChild(c)});const form=document.createElement('div');form.className='form';const props=(def.inputSchema&&def.inputSchema.properties)||{};Object.keys(props).forEach(key=>form.appendChild(field(key,props[key])));const call=document.createElement('button');call.className='btn primary';call.textContent=text.call+' '+def.name;call.onclick=async()=>{const args={};form.querySelectorAll('[data-name]').forEach(input=>{if(input.type==='checkbox')args[input.dataset.name]=input.checked;else if(input.value!=='')args[input.dataset.name]=input.type==='number'?Number(input.value):input.value});await request(def.name,args)};form.appendChild(call);card.appendChild(form);toolsEl.appendChild(card)})}
function addCall(item){calls.unshift(item);calls=calls.slice(0,50);selected=item.id;renderHistory();renderResult(item)}
function renderHistory(){historyEl.replaceChildren();calls.forEach(item=>{const row=document.createElement('div');row.className='history-item'+(item.id===selected?' active':'');row.onclick=()=>{selected=item.id;renderHistory();renderResult(item)};const n=document.createElement('div');n.className='history-name';n.textContent=item.name;const meta=document.createElement('div');meta.className='history-meta';const s=document.createElement('span');s.className='status '+(item.ok?'ok':'bad');s.textContent=item.httpStatus||'ERR';const d=document.createElement('span');d.textContent=item.duration+' ms';meta.append(s,d);row.append(n,meta);historyEl.appendChild(row)})}
 function contentBlocks(item){const blocks=[];const content=item.body?.result?.content||[];content.forEach(block=>{if(block.type==='image'&&block.data){const wrap=document.createElement('div');wrap.className='image-card';const label=document.createElement('div');label.className='image-label';label.textContent=text.image+' · '+(block.mimeType||'image/png');const image=document.createElement('img');image.src='data:'+(block.mimeType||'image/png')+';base64,'+block.data;image.alt=text.image;wrap.append(label,image);blocks.push(wrap)}else if(block.type==='text'){const pre=document.createElement('pre');pre.textContent=pretty(block.text);blocks.push(pre)}});return blocks}
 function inspectionData(item){if(item.name!=='view_tree'&&item.name!=='view_content')return null;const block=(item.body?.result?.content||[]).find(v=>v.type==='text'&&typeof v.text==='string');if(!block)return null;try{if(item.name==='view_tree'){const doc=new DOMParser().parseFromString(block.text,'application/xml');if(doc.querySelector('parsererror'))return null;const root=xmlNode(doc.documentElement,'',null);return {mode:'xml',root:root,nodes:flatten(root)}}const parsed=JSON.parse(block.text);const root=jsonNode(parsed.hierarchy,'$.hierarchy',null);return root?{mode:'json',root:root,nodes:flatten(root)}:null}catch(_){return null}}
 function xmlNode(element,parentPath,parentXpath){const same=element.parentElement?Array.from(element.parentElement.children).filter(v=>v.tagName===element.tagName):[element];const position=Math.max(1,same.indexOf(element)+1);const xpath=parentXpath+'/'+element.tagName.toLowerCase()+'['+position+']';const path=parentPath?parentPath+'.children['+(position-1)+']':'$';const attrs={};Array.from(element.attributes||[]).forEach(a=>attrs[a.name]=a.value);const bounds=readBounds(attrs);const node={id:'xml-'+Math.random().toString(36).slice(2),element:element.tagName,attrs:attrs,bounds:bounds,path:path,xpath:xpath,children:[]};Array.from(element.children||[]).forEach(child=>node.children.push(xmlNode(child,path,xpath)));return node}
 function jsonNode(raw,path,parent){if(!raw||typeof raw!=='object'||!raw.element)return null;const attrs=raw.attributes&&typeof raw.attributes==='object'?raw.attributes:{};const node={id:'json-'+Math.random().toString(36).slice(2),element:String(raw.element),attrs:attrs,bounds:raw.bounds&&typeof raw.bounds==='object'?raw.bounds:readBounds(attrs),size:raw.size||null,tap:raw.tap||null,path:path,xpath:null,children:[]};(Array.isArray(raw.children)?raw.children:[]).forEach((child,index)=>{const childNode=jsonNode(child,path+'.children['+index+']',node);if(childNode)node.children.push(childNode)});return node}
 function readBounds(attrs){if(!attrs)return null;const raw=attrs.bounds;if(typeof raw!=='string')return null;const match=raw.match(/^\[(-?\d+),(-?\d+)\]\[(-?\d+),(-?\d+)\]$/);if(!match)return null;const left=Number(match[1]),top=Number(match[2]),right=Number(match[3]),bottom=Number(match[4]);return {left:left,top:top,right:right,bottom:bottom,width:right-left,height:bottom-top}}
 function flatten(root){const nodes=[];function walk(node){nodes.push(node);node.children.forEach(walk)}if(root)walk(root);return nodes}
 function nodeLabel(node){return node.attrs?.text||node.attrs?.['content-desc']||node.attrs?.['resource-id']||node.element}
