torAll('.node-row').forEach(row=>row.classList.toggle('active',row.dataset.nodeId===node.id));inner.querySelectorAll('.inspect-box').forEach(box=>box.classList.toggle('active',box.dataset.nodeId===node.id));renderDetails(node)}function addTree(node,depth){const row=document.createElement('button');row.type='button';row.className='node-row';row.dataset.nodeId=node.id;row.title=node.path+(data.mode==='xml'?' · '+node.xpath:'');const indent=document.createElement('span');indent.className='node-indent';indent.style.setProperty('--indent',(depth*14)+'px');const kind=document.createElement('span');kind.className='node-kind';kind.textContent='<'+node.element+'>';const label=document.createElement('span');label.className='node-label';label.textContent=nodeLabel(node);row.append(indent,kind,label);row.onclick=()=>select(node);tree.appendChild(row);node.children.forEach(child=>addTree(child,depth+1))}data.nodes.forEach((node,index)=>{if(index===0)addTree(node,0)});data.nodes.filter(node=>node.bounds).forEach(node=>{const b=node.bounds;const box=document.createElement('button');box.type='button';box.className='inspect-box';box.dataset.nodeId=node.id;box.style.left=b.left+'px';box.style.top=b.top+'px';box.style.width=Math.max(2,b.width||b.right-b.left)+'px';box.style.height=Math.max(2,b.height||b.bottom-b.top)+'px';const label=document.createElement('span');label.className='inspect-box-label';label.textContent=node.element;box.appendChild(label);box.onclick=()=>select(node);inner.appendChild(box)});function renderDetails(node){detailsPanel.replaceChildren();const heading=document.createElement('div');heading.className='inspector-title';heading.textContent=text.selected+' · '+node.element;detailsPanel.appendChild(heading);const dl=document.createElement('dl');dl.className='inspector-details';const values=[[text.path,node.path]];if(node.xpath)values.push([text.xpath,node.xpath]);values.push([text.bounds,node.bounds?JSON.stringify(node.bounds):'—'],[text.size,node.size?JSON.string