 function copyText(value,button){if(!value)return;const done=()=>{const old=button.textContent;button.textContent=text.copied;setTimeout(()=>button.textContent=old,900)};if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(value).then(done).catch(()=>done());else{const area=document.createElement('textarea');area.value=value;document.body.appendChild(area);area.select();document.execCommand('copy');area.remove();done()}}
