 async function request(toolName,args){if(!token()){renderResult(null);return}const requestIdValue=++requestId;const started=performance.now();try{const response=await fetch(new URL('/mcp',location.href),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json, text/event-stream','Authorization':'Bearer '+token()},body:JSON.stringify({jsonrpc:'2.0',id:requestIdValue,method:'tools/call',params:{name:toolName,arguments:args}})});const raw=await response.text();let body;try{body=JSON.parse(raw)}catch(_){body={raw:raw}}const item={id:Date.now()+Math.random(),requestId:requestIdValue,name:toolName,args:args,httpStatus:response.status,ok:response.ok&&!body.result?.isError,duration:Math.round(performance.now()-started),body:body};addCall(item)}catch(error){addCall({id:Date.now()+Math.random(),requestId:requestIdValue,name:toolName,args:args,httpStatus:'ERR',ok:false,duration:Math.round(performance.now()-started),error:String(error)})}}
